import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Evaluation is an independent dimension","description":"","frontmatter":{"title":"Evaluation is an independent dimension","type":"adr","date":"2026-10","status":"accepted"},"headers":[],"relativePath":"graphopt/project/adrs/0003-evaluation-is-an-independent-dimension.md","filePath":"vendored/graphopt/project/adrs/0003-evaluation-is-an-independent-dimension.md"}`),a={name:`graphopt/project/adrs/0003-evaluation-is-an-independent-dimension.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0003-—-evaluation-is-an-independent-dimension" tabindex="-1">ADR 0003 — Evaluation is an independent dimension <a class="header-anchor" href="#adr-0003-—-evaluation-is-an-independent-dimension" aria-label="Permalink to “ADR 0003 — Evaluation is an independent dimension”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Adopt <strong>four independent dimensions</strong> with explicit ports, and keep them independent.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>SEMANTICS ──▶ SEARCH ──▶ EVALUATION ──▶ EXECUTION</span></span>
<span class="line"><span>   │            │             │              │</span></span>
<span class="line"><span> &quot;equivalent?&quot; &quot;explore?&quot;  &quot;how does it   &quot;what actually</span></span>
<span class="line"><span>                            look / run?&quot;    ran?&quot;</span></span></code></pre></div><p><strong>Rule.</strong> Semantics, search, evaluation and execution are independent dimensions; no layer may become responsible for another&#39;s question.</p><p>Each dimension answers exactly one question:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Question</th><th>Owns</th><th>Must not</th></tr></thead><tbody><tr><td>Semantics</td><td>Is it equivalent?</td><td><code>EGraph</code>, <code>verify_certificate</code></td><td>price or time anything</td></tr><tr><td>Search</td><td>What should we explore?</td><td><code>Engine</code>, policy</td><td>decide equivalence</td></tr><tr><td>Evaluation</td><td>What does it look like / what might run well?</td><td>profiler, cost, performance model</td><td>change the function</td></tr><tr><td>Execution</td><td>What actually ran?</td><td><code>Sink</code>, <code>Meter</code>, hardware adapter</td><td>define semantics</td></tr></tbody></table><h3 id="decisions-in-detail" tabindex="-1">Decisions in detail <a class="header-anchor" href="#decisions-in-detail" aria-label="Permalink to “Decisions in detail”">​</a></h3><ol><li><strong>Evaluation splits from execution.</strong> A <code>Profiler</code> observes a program <em>without running it on the target</em>; an <code>Executor</code> runs it; the existing <code>Meter</code> measures a run — there is <strong>no separate <code>Benchmark</code> port</strong>; <code>Meter</code> gains provenance and failure classification. <strong>Profiling does not imply a GPU</strong> — the static half is torch-free, in core.</li><li><strong>Keep the frontier; do not scalarize early.</strong> The candidate set is what <code>discover_alternatives</code> already enumerates (<code>SearchResult.alternatives</code>); selection keeps the non-dominated subset over named dimensions. A scalar <code>best()</code> is a convenience view, not the internal contract — today&#39;s <code>criteria={...}</code> weighted blend is that view. Note: <code>extract_best</code> minimizes one scalar by construction, so true multi-objective <em>extraction</em> is new work, not a re-view of the existing one.</li><li><strong>One reference hardware backend, not one architecture.</strong> The first GPU profiler/benchmarker is the first <em>instance</em> behind the ports. <code>cuda</code> / <code>rocm</code> / <code>tpu</code> names never enter core; the dependency arrow points core ◀ adapter, never core ▶ CUDA.</li><li><strong>Policy is a replaceable port, RL included.</strong> RL is a <em>policy</em> over an already-structured space — never the mechanism of reach. The first policies are random / greedy / heuristic / existing; RL is one more conforming value. <code>Policy.choose(state, actions)</code> threads through the existing <code>Engine.run</code> schedule / <code>stop</code> hook — it is not a parallel search mechanism. This <strong>amends ADR 0002 Rule 3</strong>.</li><li><strong>The performance model is a port.</strong> Initially analytical, later learned; it <em>predicts</em>, it never decides correctness and never bounds the semantic space.</li><li><strong>Benchmarks are last.</strong> Rewrite benchmarks only after the boundaries settle, around research questions, not just speed numbers.</li></ol><p><strong>Feasibility is hard; performance is soft.</strong> Two mechanisms already bound the search and must stay distinct: <code>supported_ops</code> is a <em>hard</em> feasibility bound (a form using an unlowerable op prices at <code>+inf</code> and is never selected); a performance model is a <em>soft</em> ranking (it orders feasible members and may never drop one). Invariant 8 makes this binding.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>CatOpt today proves <em>reach</em> and prices it with a scalar, static, calibrated cost model. The pipeline is lift → saturate → extract → certify → lower. Pricing is a <code>CostFn</code> (selected by a <code>Criterion</code>) over a <code>TargetProfile</code>&#39;s measured constants. Measurement exists, but only as an autotune <em>selector</em> inside one strategy (<code>Autotuned</code> via the <code>Meter</code> port), and its numbers are folded back into the cost model as multiplicative corrections.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep the scalar cost model + autotune (status quo).</strong> Rejected:</li><li><strong>Start with RL.</strong> Rejected: without a profiler, a frontier and a</li><li><strong>A new top-level <code>catopt</code> façade for the &quot;clean&quot; API.</strong> Rejected:</li><li><strong>Put program features in <code>catopt_core.profile</code>.</strong> Rejected: name</li><li><strong>Make the GPU implementation the abstraction.</strong> Rejected: CUDA is</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The engine gains an explicit <code>Policy</code> seam below <code>Strategy</code>, so</li><li><code>discover_alternatives</code> becomes the entry to a Pareto frontier, not</li><li><code>Meter</code> gains provenance and failure classification; <code>Autotuned</code></li><li>New protocols are new surface: they must be typed (<code>ty</code>), tested</li><li>The road to a learned performance model is opened without changing</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0003-evaluation-is-an-independent-dimension.html"><code>design/0003-evaluation-is-an-independent-dimension.md</code></a>.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};